('reading', 'true_false_not_given', 'Leisure', 'hard', 6.5, 'Members who rejoin more than six months after cancelling must pay the joining fee again.', '22000000-0000-0000-0000-000000000001', null, null, '"FALSE"', 'The passage states members who rejoin "within six months" pay the fee again, "whereas members who rejoin after more than six months are exempt from this fee" — the opposite of the statement.', 'Watch for a contrast word like "whereas" — it usually signals that the two halves of a sentence describe opposite outcomes.', '{"true_false_not_given"}', 65, 7, false),
('reading', 'true_false_not_given', 'Leisure', 'easy', 4.5, 'All new members must attend an induction session before using gym equipment.', '22000000-0000-0000-0000-000000000001', null, null, '"TRUE"', 'The Membership Types section states "new members must complete a short induction session with a member of staff before using the gymnasium equipment for the first time."', 'This is a direct restatement, so confirm each key word (new members, induction, before, gym equipment) is matched rather than contradicted.', '{"true_false_not_given"}', 45, 8, false),
('reading', 'short_answer', 'Leisure', 'easy', 4.5, 'How many guests, at most, may a member bring per visit?', '22000000-0000-0000-0000-000000000001', null, null, '["two","two guests"]', 'The Guest Policy section states "Members may bring up to two guests per visit."', 'For short-answer number questions, write the word or figure exactly as given rather than adding extra description.', '{"short_answer"}', 40, 9, false),
('reading', 'short_answer', 'Leisure', 'medium', 5.5, 'For how many days is lost property kept before it is donated to charity?', '22000000-0000-0000-0000-000000000001', null, null, '["28 days","twenty-eight days"]', 'The final section states "Lost property is held for twenty-eight days before being donated to a local charity."', 'The lost-property paragraph is short and near the end of the text, so questions about it are usually answered by the final one or two sentences.', '{"short_answer"}', 45, 10, false),
('reading', 'matching_features', 'Leisure', 'medium', 5.5, 'Match the description to the correct membership type: Includes access to the gymnasium and studio only, with no pool or sauna access.', '22000000-0000-0000-0000-000000000001', null, '["Bronze","Silver","Gold"]', '"Bronze"', 'The passage states the Bronze membership "grants access to the gymnasium and the group exercise studio only," with no mention of pool or sauna access.', 'Look for the membership tier whose description contains a limiting word like "only" — this usually signals the most basic tier.', '{"matching_features"}', 60, 11, false),
('reading', 'matching_features', 'Leisure', 'medium', 6, 'Match the description to the correct membership type: Includes unlimited access to the pool and sauna, but no personal training sessions.', '22000000-0000-0000-0000-000000000001', null, '["Bronze","Silver","Gold"]', '"Silver"', 'The Silver membership "includes everything in Bronze plus unlimited use of the swimming pool and sauna," but personal training sessions are only added at the Gold tier, making this description unique to Silver.', 'Since Gold includes everything Silver has, use the absence of a Gold-only feature (personal training) to rule Gold out.', '{"matching_features"}', 65, 12, false),
('reading', 'matching_features', 'Leisure', 'medium', 6, 'Match the description to the correct membership type: Includes priority booking for the group exercise studio.', '22000000-0000-0000-0000-000000000001', null, '["Bronze","Silver","Gold"]', '"Gold"', 'The passage states the Gold membership includes "priority booking for the group exercise studio," a feature not mentioned for Bronze or Silver.', 'Priority booking is only mentioned once in the whole passage, directly after the Gold price, making this an easy word-match once located.', '{"matching_features"}', 55, 13, false),
('reading', 'short_answer', 'Workplace', 'easy', 5, 'How many months of continuous service must an employee complete before applying for flexible working?', '22000000-0000-0000-0000-000000000002', null, null, '["six months","6 months"]', 'The passage states "Employees who have completed at least six months of continuous service may apply for flexible working."', 'The eligibility condition always appears in the first sentence of a policy paragraph — check there before scanning further.', '{"short_answer"}', 45, 1, false),
('reading', 'note_completion', 'Workplace', 'easy', 5, 'Complete the note using NO MORE THAN FOUR WORDS: Employees must apply for flexible working in writing using the ______.', '22000000-0000-0000-0000-000000000002', null, null, '"Flexible Working Request Form"', 'The passage states "Applications must be submitted in writing to a direct line manager using the Flexible Working Request Form."', 'Named forms and documents are usually capitalised in the text, which makes them easy to spot when scanning for this type of answer.', '{"note_completion"}', 50, 2, false),
('reading', 'true_false_not_given', 'Workplace', 'medium', 5.5, 'Line managers have one month to respond to a flexible working request.', '22000000-0000-0000-0000-000000000002', null, null, '"FALSE"', 'The passage states line managers "are required to respond within twenty-one days," which is shorter than one month, so the statement is incorrect.', 'Convert time periods to the same unit before comparing — twenty-one days is clearly less than the thirty or so days in "one month."', '{"true_false_not_given"}', 55, 3, false),
('reading', 'true_false_not_given', 'Workplace', 'medium', 5.5, 'Employees can appeal a declined flexible working request within two weeks of the decision.', '22000000-0000-0000-0000-000000000002', null, null, '"TRUE"', 'The passage states employees "may appeal to the Human Resources department within fourteen days of receiving the decision," and fourteen days is equivalent to two weeks.', 'Recognise that "fourteen days" and "two weeks" are equivalent paraphrases of the same time period.', '{"true_false_not_given"}', 55, 4, false),
