('reading', 'matching_information', 'Workplace', 'medium', 6, 'In which section of the handbook is the return-to-work interview described?', '22000000-0000-0000-0000-000000000002', null, '["Flexible Working Arrangements","Annual Leave","Sick Leave and Return-to-Work Procedure","Parental Leave","Training and Professional Development Scheme"]', '"Sick Leave and Return-to-Work Procedure"', 'The return-to-work interview is described in the section headed "Sick Leave and Return-to-Work Procedure," which states employees "are required to complete a brief return-to-work interview with their line manager."', 'The section heading itself often contains the key term from the question, so scan the headings first before reading paragraph content.', '{"matching_information"}', 55, 9, false),
('reading', 'short_answer', 'Workplace', 'medium', 5.5, 'How many weeks notice should employees ideally give before taking parental leave?', '22000000-0000-0000-0000-000000000002', null, null, '["fifteen weeks","15 weeks"]', 'The Parental Leave section states employees should inform their manager and HR "no later than fifteen weeks before the expected date."', 'The word "notice" in the question should lead you to a sentence describing when to inform someone, not when leave actually begins.', '{"short_answer"}', 45, 10, false),
