('50000000-0000-0000-0000-000000000001', 'part1', 'group-hometown-travel', 'Hometown', null, '["Where is your hometown?","What do you like most about your hometown?","Has your hometown changed much since you were a child?","Would you like to continue living there in the future?"]'),
('50000000-0000-0000-0000-000000000002', 'part1', 'group-hobbies-skills', 'Hobbies', null, '["What do you like to do in your free time?","Is this something you have enjoyed since childhood?","Do you prefer hobbies you do alone or with other people?","Would you like to try a new hobby in the future?"]'),
('50000000-0000-0000-0000-000000000003', 'part2', 'group-hometown-travel', 'A memorable trip', 'Describe a memorable trip you have been on. You should say: where you went, who you went with, what you did there, and explain why this trip was memorable for you.', '["Describe a memorable trip you have been on."]'),
('50000000-0000-0000-0000-000000000004', 'part2', 'group-hobbies-skills', 'A skill you would like to learn', 'Describe a skill you would like to learn. You should say: what the skill is, why you want to learn it, how you would learn it, and explain how learning this skill would help you.', '["Describe a skill you would like to learn."]'),
('50000000-0000-0000-0000-000000000005', 'part3', 'group-hometown-travel', 'Travel and tourism', null, '["How has tourism changed in your country over the last twenty years?","What are the benefits and drawbacks of tourism for a local economy?","Do you think international travel will become more or less common in the future? Why?","Some people say travelling abroad is more valuable than studying it in books — do you agree?"]'),
('50000000-0000-0000-0000-000000000006', 'part3', 'group-hobbies-skills', 'Skills and education', null, '["Do you think schools should teach practical skills alongside academic subjects?","How has the internet changed the way people learn new skills?","Is it more difficult for adults to learn new skills than for children? Why?","What skills do you think will become more important in the next twenty years?"]'),
('52000000-0000-0000-0000-000000000001', 'part1', 'group-person-admire', 'People you admire', null, '["Who is someone you admire?","Why do you admire this person?","Do you know any people in your daily life whom you admire?","Has the person you admire changed over the years?"]'),
('52000000-0000-0000-0000-000000000002', 'part2', 'group-person-admire', 'A person you admire', 'Describe a person you admire. You should say: who this person is, how you know this person, what qualities this person has, and explain why you admire this person.', '["Describe a person you admire."]'),
('52000000-0000-0000-0000-000000000003', 'part3', 'group-person-admire', 'Role models and influence', null, '["What qualities make someone a good role model?","Do you think celebrities are good role models for young people nowadays?","Why do some people prefer to admire ordinary people rather than famous figures?","How can positive role models influence a whole society?"]'),
('52000000-0000-0000-0000-000000000004', 'part1', 'group-family-member', 'Family', null, '["Who are the members of your family?","Which family member are you closest to?","Do you often spend time with your family?","How important is family to people in your country?"]'),
('52000000-0000-0000-0000-000000000005', 'part2', 'group-family-member', 'A family member you are close to', 'Describe a family member you are close to. You should say: who this person is, how long you have known them, what you usually do together, and explain why you are close to this person.', '["Describe a family member you are close to."]'),
