('52000000-0000-0000-0000-000000000011', 'part2', 'group-teacher-influence', 'A teacher who influenced you', 'Describe a teacher who influenced you. You should say: who this teacher was, what subject they taught, what made them memorable, and explain how this teacher influenced you.', '["Describe a teacher who influenced you."]'),
('52000000-0000-0000-0000-000000000012', 'part3', 'group-teacher-influence', 'Education and the role of teachers', null, '["What qualities should a good teacher have?","How has the role of teachers changed with the growth of online learning?","Do you think teachers deserve more respect and higher salaries in society?","Can technology ever fully replace teachers in the classroom?"]'),
('52000000-0000-0000-0000-000000000013', 'part1', 'group-leader-respect', 'Leadership', null, '["Do you follow news about political or community leaders?","What kind of leader do you respect?","Have you ever had to lead a group of people?","Do you think leadership skills can be taught?"]'),
('52000000-0000-0000-0000-000000000014', 'part2', 'group-leader-respect', 'A leader you respect', 'Describe a leader you respect. You should say: who this leader is, what they have done, what qualities they have, and explain why you respect this leader.', '["Describe a leader you respect."]'),
